<script>
const unitData={
  1:{
    subtitle:"Welcome to our new course",
    masterTitle:"Non-defining relative clauses",
    date1:"04 JUL 2016",
    desc1:"Non-defining relative clauses are a speaker's friend. Dan teaches us five ways to use them in this bite-sized video.",
    type2:"News Review",date2:"05 JUL 2016",
    desc2:"NASA's Juno mission has arrived at Jupiter. Find out more with Neil and Sian as they look at how the world's media is reacting and the words you need to talk about the story.",
    img2:"013.jpg"
  },
  4:{
    subtitle:"Grammar, news, vocabulary and pronunciation",
    masterTitle:"Linking words of contrast",date1:"25 JUL 2016",
    desc1:"Dan uses linking words of contrast to destroy four myths about English people.",
    type2:"News Review",date2:"26 JUL 2016",
    desc2:"Can chickens stop you getting bitten by mosquitoes? Join Rob and Sian in News Review as they bring you this exciting story and the language you need to understand it.",
    img2:"019.png"
  },
  7:{
    subtitle:"Grammar, news, vocabulary and pronunciation",
    masterTitle:"Mixed conditionals",date1:"15 AUG 2016",
    desc1:"They say you shouldn't mix your drinks, but should you mix your conditionals? Find out in this Masterclass with Dan.",
    type2:"News Review",date2:"16 AUG 2016",
    desc2:"Brazil has won a gold medal in athletics in a shocking pole vault final. Join Sian and Neil in News Review as they bring you this exciting story and the language you need to understand it.",
    img2:"020.png"
  }
};
let currentUnit=1, currentTab="sessions";
const main=document.getElementById("mainContent");
function setUnit(n){
 currentUnit=n;const d=unitData[n]||unitData[1];
 document.getElementById("unitCircle").textContent=n;
 document.getElementById("unitTitle").textContent=`Unit ${n}: Towards advanced`;
 document.getElementById("unitSubtitle").textContent=n===1?d.subtitle:unitData[7].subtitle;
 document.querySelectorAll(".unit-button").forEach((b,i)=>b.classList.toggle("active",i+1===n));
 render();
}
const units=document.getElementById("unitButtons"), nums=document.getElementById("unitNumbers");
for(let i=1;i<=30;i++){
 const b=document.createElement("button");b.className="unit-button btn";b.setAttribute("aria-label","Unit "+i);b.onclick=()=>setUnit(i);units.appendChild(b);
 const s=document.createElement("span");s.textContent=i;s.onclick=()=>setUnit(i);nums.appendChild(s);
}
function setTab(tab){
 currentTab=tab;
 document.querySelectorAll(".tab").forEach(t=>t.classList.toggle("active",t.dataset.tab===tab));
 render();
}
document.querySelectorAll(".tab").forEach(t=>t.onclick=()=>setTab(t.dataset.tab));
document.getElementById("toggleSelector").onclick=()=>{
 const closed=document.getElementById("selector").classList.toggle("closed");
 const tabs=document.getElementById("tabs");tabs.classList.toggle("closed",closed);
 document.getElementById("toggleSelector").innerHTML=closed?'Open unit selector <span class="arrow">⌄</span>':'Close unit selector <span class="arrow">⌃</span>';
};
function masterImage(d){
 if(currentUnit===1) return `<img class="session-image master" src="__PLACEHOLDER_ASSETS_BASE_DIR__/010.jpg" width="220" height="168" alt="BBC Masterclass: ${d.masterTitle}">`;
 return `<div class="session-image master custom-board" role="img" aria-label="BBC Masterclass: ${d.masterTitle}"><span class="board-label">BBC MASTERCLASS</span><span class="board-title">${d.masterTitle}</span></div>`;
}
function renderSessions(){
 const d=unitData[currentUnit]||unitData[1];
 main.innerHTML=`<div class="sessions-wrap">
  <article class="session"><div class="session-image-box">${masterImage(d)}</div><div class="session-info">
   <h2>Session 1</h2><span class="activity">1 ACTIVITY</span><div class="session-type">BBC Masterclass</div>
   <p class="date">${d.date1}</p><p class="description">${d.desc1}</p></div></article>
  <article class="session"><div class="session-image-box"><img class="session-image" src="__PLACEHOLDER_ASSETS_BASE_DIR__/${d.img2}" width="315" height="188" alt=""></div><div class="session-info">
   <h2>Session 2</h2><span class="activity">1 ACTIVITY</span><div class="session-type">${d.type2}</div>
   <p class="date">${d.date2}</p><p class="description">${d.desc2}</p></div></article>
 </div>`;
}
function sideCards(grammar){
 return `<aside class="reference-side">
  <div class="side-card"><a class="btn" href="#" onclick="setTab('sessions');return false">View sessions in this unit &gt;</a></div>
  <div class="side-card">Session ${grammar?"Vocabulary":"Grammar"}<a class="btn" href="#" onclick="setTab('${grammar?"vocabulary":"grammar"}');return false">Practise this ${grammar?"vocabulary":"grammar"} &gt;</a></div>
  <div class="download btn"><span class="icon">⬇</span><span><small>DOWNLOAD CENTRE</small>Latest course content</span></div>
 </aside>`;
}
function renderVocabulary(){
 main.innerHTML=`<div class="reference-wrap"><div class="reference-main"><h1>Vocabulary Reference</h1>
 <h2>Session 2 - News Review</h2>
 <div class="vocab-entry"><strong>an upset</strong>when someone beats the team or player that was expected to win</div>
 <div class="vocab-entry"><strong>pull something off</strong>to succeed in doing something that is difficult</div>
 <div class="vocab-entry"><strong>egg somebody on</strong>encourage someone or urge someone to do something (especially something they shouldn't do)</div>
 <div class="vocab-entry"><strong>pandemonium</strong>a situation in which there is a lot of noise or craziness because people are excited, angry, or frightened</div>
 <h2>Session 3 - Lingohack</h2>
 <div class="vocab-entry"><strong>medal tally</strong>number of medals won</div>
 <div class="vocab-entry"><strong>feeds on</strong>eats, consumes (especially for animals)</div>
 <div class="vocab-entry"><strong>cheating</strong>breaking the rules of a competition</div>
 <h2>Session 4 - Pygmalion: 8 uses of 'round'</h2>
 <div class="vocab-entry"><strong>driving him around the bend (C2)</strong>making him very annoyed</div>
 <div class="vocab-entry"><strong>comes round (C2)</strong>begins to accept something previously rejected</div>
 <div class="vocab-entry"><strong>round and round (B2)</strong>moving in a circular direction</div>
 <div class="vocab-entry"><strong>round the clock (C1)</strong>all day and all night</div>
 <div class="vocab-entry"><strong>round (A2)</strong>on all sides (of something)</div>
 <div class="vocab-entry"><strong>goes round to (A2)</strong>visits</div>
 <div class="vocab-entry"><strong>in a roundabout kind of way (C2)</strong>more or less; sort of</div>
 <div class="vocab-entry"><strong>round off (B2)</strong>finish; complete (something)</div>
 <a class="practice-button btn" href="#">Practise Vocabulary &nbsp;›</a></div>${sideCards(true)}</div>`;
}
function renderGrammar(){
 main.innerHTML=`<div class="reference-wrap"><div class="reference-main"><h1>Grammar Reference</h1>
 <h2>Conditionals review</h2><h3>Meaning and use</h3>
 <p>Conditional sentences express a connection between two actions or states. One thing happens because of another. These connections can be general, specific, likely, unlikely, real or imagined.</p>
 <p>Although there are quite a few different ways of forming conditional sentences there are common patterns known as zero, first, second and third conditionals.</p>
 <p><b>Zero conditionals</b><br>Used to refer to general truths, scientific facts and the predictable results of particular actions. One thing happens and because of this something else happens. In zero conditionals <b>if</b> and <b>when</b> have the same meaning.</p>
 <p><i>If you heat water enough, it boils.</i></p>
 <h3>First conditionals</h3><p>We use the first conditional to talk about a possible situation and its result.</p>
 <h3>Second conditionals</h3><p>We use the second conditional to talk about an imaginary or unlikely situation.</p>
 </div>${sideCards(false)}</div>`;
}
function render(){if(currentTab==="sessions")renderSessions();else if(currentTab==="vocabulary")renderVocabulary();else renderGrammar()}
setUnit(1);
</script>
<style>
